// reproduce.js
// This script uses Lighthouse’s Node API to run only the "offline-start-url" audit
// on https://www.bhphotovideo.com and prints out the audit result.
// On a correct offline implementation you should get score: 1, but the bug shows score: 0.

const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

async function runOfflineAudit() {
  // 1) Launch a headless Chrome
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--disable-gpu']
  });

  // 2) Prepare Lighthouse options
  const options = {
    port: chrome.port,
    // disable resetting SW / storage so we keep the registered service worker
    disableStorageReset: true,
    logLevel: 'info'
  };

  // 3) Custom config: only run the offline-start-url audit
  const config = {
    extends: 'lighthouse:default',
    settings: {
      onlyAudits: ['offline-start-url'],
    }
  };

  // 4) Run Lighthouse
  const runnerResult = await lighthouse('https://www.bhphotovideo.com', options, config);
  const lhr = runnerResult.lhr;

  // 5) Print the offline-start-url audit
  console.log('=== offline-start-url audit result ===');
  console.log(JSON.stringify(lhr.audits['offline-start-url'], null, 2));

  // 6) Shutdown
  await chrome.kill();
}

runOfflineAudit().catch(err => {
  console.error(err);
  process.exit(1);
});
